{
  "name": "cart",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Shopping cart totals (plain JS, no dependencies).",
  "scripts": {
    "test": "node --test \"test/**/*.test.js\""
  }
}
/** Line total in cents for {priceCents, qty}. */
export function lineTotal(item) {
  return item.priceCents * item.qty;
}

/**
 * Cart total in cents. `discount` is an optional {percent} applied to the subtotal,
 * rounded half up to the nearest cent.
 */
export function cartTotal(items, discount) {
  const subtotal = items.reduce((sum, it) => sum + lineTotal(it), 0);
  if (!discount) return subtotal;
  return subtotal - Math.floor((subtotal * discount.percent) / 100);
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { cartTotal, lineTotal } from '../src/cart.js';

test('lineTotal', () => {
  assert.equal(lineTotal({ priceCents: 250, qty: 3 }), 750);
});

test('cartTotal without discount', () => {
  assert.equal(cartTotal([{ priceCents: 100, qty: 2 }, { priceCents: 50, qty: 1 }]), 250);
});

test('cartTotal with 15% discount rounds the discount half up', () => {
  // subtotal 1050, 15% = 157.5 → discount 158 → total 892
  assert.equal(cartTotal([{ priceCents: 1050, qty: 1 }], { percent: 15 }), 892);
});
